1	import { Block, Text } from "@prototyp/skeletor";
2	import {
3	  type EventTimelineItem,
4	  ShieldState_Tags,
5	} from "@unomed/react-native-matrix-sdk";
6	import { format } from "date-fns";
7	import { type FC, useMemo, useState } from "react";
8	import { Image, Modal, StyleSheet } from "react-native";
9	import { Colors, TextSize } from "shared/styles";
10	import { Button } from "../button";
11	import { DeliveryStatus } from "../delivery-status";
12	
13	interface Props {
14	  event: EventTimelineItem;
15	  isUser: boolean;
16	  isEdited?: boolean;
17	}
18	
19	export const MessageTimestamp: FC<Props> = ({ event, isUser, isEdited }) => {
20	  const [modalVisible, setModalVisible] = useState(false);
21	  const shieldState = useMemo(
22	    () => event.lazyProvider.getShields(false),
23	    [event],
24	  );
25	  const isRed = shieldState?.tag === ShieldState_Tags.Red;
26	  const isGrey = shieldState?.tag === ShieldState_Tags.Grey;
27	  const hasShield = isRed || isGrey;
28	  const shieldMessage =
29	    shieldState && "inner" in shieldState ? shieldState.inner.message : "";
30	
31	  return (
32	    <>
33	      {hasShield && !isUser ? (
34	        <Button.Wrapper onPress={() => setModalVisible(true)} hitSlop={12}>
35	          <Block
36	            flexDirection={isUser ? "row" : "row-reverse"}
37	            gap={4}
38	            align="center"
39	          >
40	            <Image
41	              source={require("assets/icons/info.png")}
42	              style={styles.infoIcon}
43	              tintColor={Colors.error}
44	            />
45	            {isEdited && (
46	              <Text size={TextSize.tiny} color={Colors.white50}>
47	                (edited)
48	              </Text>
49	            )}
50	            <Text size={TextSize.tiny} color={Colors.error}>
51	              {format(Number(event.timestamp), "HH:mm")}
52	            </Text>
53	          </Block>
54	        </Button.Wrapper>
55	      ) : (
56	        <Block flexDirection="row" gap={8} align="center">
57	          {isUser && <DeliveryStatus event={event} />}
58	          {isEdited && (
59	            <Text size={TextSize.tiny} color={Colors.white50}>
60	              (edited)
61	            </Text>
62	          )}
63	          <Text size={TextSize.tiny} color={Colors.white50}>
64	            {format(Number(event.timestamp), "HH:mm")}
65	          </Text>
66	        </Block>
67	      )}
68	
69	      <Modal visible={modalVisible} transparent animationType="fade">
70	        <Block
71	          width="100%"
72	          height="100%"
73	          justify="center"
74	          align="center"
75	          background={Colors.black70}
76	          paddings={[40, 20]}
77	        >
78	          <Block
79	            width="100%"
80	            background={Colors.blackMinus2}
81	            paddings={20}
82	            border={{ borderRadius: 36 }}
83	            gap={12}
84	          >
85	            <Text size={TextSize.large}>{isRed ? "Warning" : "Info"}</Text>
86	            <Text size={TextSize.small} color={Colors.white50}>
87	              {shieldMessage}
88	            </Text>
89	            <Button.Secondary
90	              onPress={() => setModalVisible(false)}
91	              width="100%"
92	              size="medium"
93	            >
94	              I understand
95	            </Button.Secondary>
96	          </Block>
97	        </Block>
98	      </Modal>
99	    </>
100	  );
101	};
102	
103	const styles = StyleSheet.create({
104	  infoIcon: {
105	    width: 14,
106	    height: 14,
107	  },
108	});
