1	import { Text } from "@prototyp/skeletor";
2	import type { FC } from "react";
3	import { Colors, TextSize } from "shared/styles";
4	
5	interface Props {
6	  body: string;
7	  mentionMap: Map<string, string>;
8	  isUser: boolean;
9	  onMentionPress?: (member: MemberDetailsPayload) => void;
10	}
11	
12	export const MentionText: FC<Props> = ({
13	  body,
14	  mentionMap,
15	  isUser,
16	  onMentionPress,
17	}) => {
18	  const escapedNames = Array.from(mentionMap.keys())
19	    .sort((a, b) => b.length - a.length)
20	    .map((name) => name.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"));
21	
22	  const pattern = new RegExp(`@(${escapedNames.join("|")})`, "gi");
23	  const parts = body.split(pattern);
24	
25	  return (
26	    <Text size={TextSize.small} color="white">
27	      {parts.map((part, i) => {
28	        if (i % 2 === 1) {
29	          const userId = mentionMap.get(part.toLowerCase());
30	          if (userId) {
31	            return (
32	              <Text
33	                key={i}
34	                font="InstrumentSans-Semibold"
35	                color={isUser ? Colors.white : Colors.primary}
36	                onPress={() =>
37	                  onMentionPress?.({
38	                    userId,
39	                    displayName: part,
40	                    avatarUrl: null,
41	                  })
42	                }
43	              >
44	                {`@${part}`}
45	              </Text>
46	            );
47	          }
48	        }
49	        return part;
50	      })}
51	    </Text>
52	  );
53	};
